mapper.insert:
INSERT INTO ai_call_logs (
  id, kind, task, provider, outcome, elapsed_ms, input_units, error_message, created_at
) VALUES (
  #{id}, #{kind}, #{task}, #{provider}, #{outcome}, #{elapsedMs}, #{inputUnits},
  #{errorMessage}, #{createdAt}
)

mapper.select:
SELECT AVG(elapsed_ms)
FROM ai_call_logs
WHERE created_at >= #{since}
  AND outcome = #{outcome}
